bool bits(const Spins&a,const Spins&b){for(int i=0;i<2;i++)for(size_t j=0;j<a[i].size();j++)for(int k=0;k<3;k++)if(a[i][j][k]!=b[i][j][k])return false;return true;}
std::array<double,2> ph_sd(const Spins&m,const Spins&H){std::array<double,2>r{};for(int i=0;i<2;i++)for(size_t j=0;j<m[i].size();j++)r[i]=std::max(r[i],norm(xprod(m[i][j],H[i][j])));return r;}
void require(bool a){if(!a)throw std::runtime_error("selftest failed");}
