 auto a=rational_sd({0,0,1},{0,0,0},1e-12,3e5);require(a.x==0&&a.y==0&&a.z==1);int r=0;require(choose_sd({2,1,4},1,r)==MAX_SD);require(choose_sd({2,1,4},2,r)==MAX_SD);require(choose_sd({1e-28,1e-13,1e2},1,r)==MIN_SD);require(choose_sd({0,0,0},1,r)==MIN_SD&&r==1);require(choose_sd({1,-1,1},2,r)==2*MIN_SD&&r==2);require(choose_sd({1,1,1},1,r)==MAX_SD&&r==0);require(choose_sd({1,1e-320,0},1,r)==MAX_SD);require(choose_sd({0,1e-320,1},1,r)==MIN_SD); // underflow first predicate -> alternate
