 if(std::string(argv[5])=="resume_test"){SD full=sd_restore(argv[6]);sd_checkpoint(out/"copied100.bin",full);SD resumed=sd_restore(out/"copied100.bin");auto ef=model.eval(full.m);std::ifstream fa(std::filesystem::path(argv[6]).parent_path()/"final_H_A.bin",std::ios::binary),fb(std::filesystem::path(argv[6]).parent_path()/"final_H_B.bin",std::ios::binary);for(int i=0;i<2;i++)for(auto&q:ef.H[i]){double v[3];(i==0?fa:fb).read((char*)v,sizeof(v));require(q.x==v[0]&&q.y==v[1]&&q.z==v[2]);}for(int k=0;k<5;k++){auto er=model.eval(resumed.m);auto x=advance_sd(full,ef.H),y=advance_sd(resumed,er.H);ef=model.eval(full.m);require(bits(full.m,resumed.m)&&bits(full.prev,resumed.prev)&&bits(full.Gprev,resumed.Gprev)&&full.dt==resumed.dt&&full.aux==resumed.aux&&full.resets==resumed.resets&&x.mm==y.mm&&x.mg==y.mg&&x.gg==y.gg);}sd_checkpoint(out/"continuous105.bin",full);sd_checkpoint(out/"restored105.bin",resumed);std::ofstream(out/"result.json")<<"{\"state_history_control_exact\":true,\"initial_cached100_field_exact\":true,\"additional_updates5_each\":true,\"original100_not_rerun\":true}\n";check();return 0;}if(std::string(argv[5])=="test"){tests(model,s.m,out);check();return 0;}if(std::string(argv[5])!="run")throw std::runtime_error("mode");if(std::string(argv[6])!="-"){s=sd_restore(argv[6]);}e=model.eval(s.m);ready=true;snapshot(out/"initial.bin",s.m);save_eval(out,"initial",e);std::ofstream h(out/"history.csv");h<<std::setprecision(17)<<"update,prime,dt_s,reset,bb_mm,bb_mg,bb_gg,pre_A_Apm,pre_B_Apm,pre_A_mxh,sample_available,post_A_Apm,post_B_Apm,E_pre_J,E_post_J,stable_delta_J,old_science_stable,ideal_raw_max\n";std::string status="global10000_update_cap";double window_delta=0,window_force=e.residual;int stagnant=0;
 while(s.updates<10000){check();auto pre=s.m;auto before=e;auto residual=ph_sd(pre,before.H);bool prime=s.updates==0;BB b=advance_sd(s,before.H);e=model.eval(s.m);auto post=ph_sd(s.m,e.H);double de=stable_delta(model,pre,s.m,before,e);s.stable=(std::max(post[0],post[1])<=.6&&std::abs(de)/model.scale<=1e-8)?s.stable+1:0;bool stop=!prime&&residual[0]/3e5<=5e-5;h<<s.updates<<','<<prime<<','<<s.dt<<','<<s.resets<<','<<b.mm<<','<<b.mg<<','<<b.gg<<','<<residual[0]<<','<<residual[1]<<','<<residual[0]/3e5<<','<<!prime<<','<<post[0]<<','<<post[1]<<','<<before.E<<','<<e.E<<','<<de<<','<<s.stable<<','<<SD_RAW_MAX_LAST<<'\n';h.flush();window_delta+=de;bool stagnant_stop=false;if(s.updates%500==0){bool no_improvement=-window_delta<=100*std::numeric_limits<double>::epsilon()*model.scale&&e.residual>=window_force;stagnant=no_improvement?stagnant+1:0;std::ofstream w(out/"stagnation.csv",std::ios::app);w<<std::setprecision(17)<<s.updates<<','<<window_delta<<','<<window_force<<','<<e.residual<<','<<stagnant<<'\n';window_delta=0;window_force=e.residual;stagnant_stop=stagnant>=2;}if(s.updates==1||s.updates==10||s.updates==100||s.updates%250==0||s.updates==10000||stop){snapshot(out/("step_"+std::to_string(s.updates)+".bin"),s.m);sd_checkpoint(out/("checkpoint_"+std::to_string(s.updates)+".bin"),s);}if(stop){snapshot(out/"stop_pre.bin",pre);save_eval(out,"stop_pre",before);snapshot(out/"stop_post.bin",s.m);save_eval(out,"stop_post",e);status="BORIS_A_pre_mxh_single_schedule_stop";break;}if(stagnant_stop){status="two500window_no_energy_joint_improvement";break;}check();}
